\title[A division-free theory of Gaussian binomial coefficients]
{A Division-Free Theory of Gaussian Binomial Coefficients:\\
Rothe's $q$-Binomial Theorem, the $q$-Vandermonde Convolution,\\
and Their Consequences over Arbitrary Commutative Rings}

\author{Aristotle}
\date{September 12, 2026}

\begin{document}

\begin{abstract}
We develop the theory of Gaussian binomial coefficients $\qb{n}{k}_q$ from a
division-free starting point: instead of the classical quotient of
$q$-factorials, we take as definition the $q$-Pascal recursion
$\qb{n+1}{k+1}_q = \qb{n}{k}_q + q^{k+1}\qb{n}{k+1}_q$, which makes sense over an
arbitrary commutative semiring. From this we derive the second ($q$-reflected)
Pascal recursion, Rothe's $q$-binomial theorem
$\prod_{i<n}(1+q^ix) = \sum_k q^{\binom k2}\qb nk_q x^k$, and the $q$-Vandermonde
convolution
$\qb{m+n}{k}_q = \sum_j q^{(m-j)(k-j)}\qb mj_q\qb{n}{k-j}_q$,
both valid for arbitrary $q$ and $x$ in a commutative ring. The only step of the
second proof not formally valid over a general ring --- cancellation of the
factor $q^{\binom k2}$ produced by coefficient extraction --- is isolated by a
universality principle: $\qb nk_q$ commutes with every ring homomorphism, so the
identity may be proved once in the integral domain $\Z[X]$ with $q = X$, where
cancellation is legitimate, and transported everywhere by evaluation. We then
deduce, in the same style, the cleared Gauss product formula, symmetry, Gauss'
alternating sum, a $q$-analogue of the central binomial identity, the
Goldman--Rota recurrence for Galois numbers, the Rogers--Szeg\H{o} three-term
ladder with Gauss' evaluations at $x=-1$, Cauchy's reciprocal $q$-binomial
theorem in unit form together with the negative $q$-Vandermonde convolution,
polynomiality (monic of degree $k(n-k)$ with non-negative coefficients), the
$q$-Lucas theorem at a primitive root of unity with the $q=-1$ phenomenon as a
special case, and a bridge to the line counts of the projective space
$PG(3,q)$.
\end{abstract}

\maketitle

\section{Introduction}

The Gaussian binomial coefficient is usually introduced as a quotient. With the
$q$-integer $[n]_q = 1+q+\cdots+q^{n-1}$ and the $q$-factorial
$[n]_q! = [1]_q[2]_q\cdots[n]_q$, one sets
\begin{equation}\label{eq:quotient}
  \qb nk_q = \frac{[n]_q!}{[k]_q!\,[n-k]_q!}.
\end{equation}
This is convenient but structurally misleading. Formula~\eqref{eq:quotient}
presupposes that the $q$-integers are invertible, which is false in most rings of
interest and dramatically false at a root of unity --- precisely where the theory
is most interesting. Moreover the fact that \eqref{eq:quotient} \emph{is} a
polynomial, let alone one with non-negative coefficients, is invisible in the
definition.

Throughout, $R$ is a commutative semiring (a commutative ring when subtraction is
needed) and $q \in R$ is arbitrary.

\begin{definition}[$q$-Pascal definition]\label{def:qb}
For $n,k \in \N$ define $\qb nk_q \in R$ by
\begin{equation}\label{eq:pascal1}
  \qb n0_q = 1,\qquad \qb{0}{k+1}_q = 0,\qquad
  \qb{n+1}{k+1}_q = \qb nk_q + q^{k+1}\qb{n}{k+1}_q .
\end{equation}
\end{definition}

Definition~\ref{def:qb} uses only addition and multiplication. Three consequences
are immediate and free:
\begin{enumerate}
  \item \emph{Universality.} $\qb nk_q$ is the image of the universal element
    $\qb nk_X \in \Z[X]$ under $X \mapsto q$; for every semiring homomorphism
    $f\colon R \to S$ one has $f(\qb nk_q) = \qb nk_{f(q)}$.
  \item \emph{Universality is a proof technique.} Any identity between
    $+,\times$-expressions in $q$ valid in $\Z[X]$ with $q=X$ is valid in every
    commutative ring. Since $\Z[X]$ is an integral domain, cancellation by a
    nonzero element is available there and only there.
  \item \emph{Positivity.} The recursion never subtracts, so
    $\qb nk_X \in \N[X]$.
\end{enumerate}

Notation: $\binom k2 = k(k-1)/2$ is an ordinary binomial coefficient (no
subscript $q$); $(q;q)_m = \prod_{i=1}^m (1-q^i)$ is the $q$-Pochhammer symbol;
subtractions in index positions are truncated ($n-k=0$ for $k \ge n$), which is
harmless because the relevant coefficients vanish there.

\section{Basic theory}

\begin{lemma}\label{lem:basic}
For all $q \in R$: \textup{(i)} $\qb n0_q = 1$; \textup{(ii)} $\qb nk_q = 0$ for
$n<k$; \textup{(iii)} $\qb nn_q = 1$; \textup{(iv)}
$\qb n1_q = \sum_{i=0}^{n-1}q^i = [n]_q$.
\end{lemma}

\begin{proof}
(i) and (ii) are inductions on $n$ using \eqref{eq:pascal1}; in (ii) both terms on
the right vanish by hypothesis. For (iii),
$\qb{n+1}{n+1}_q = \qb nn_q + q^{n+1}\qb{n}{n+1}_q = 1+0$. For (iv),
$\qb{n+1}{1}_q = \qb n0_q + q\qb n1_q = 1 + q\sum_{i<n}q^i$.
\end{proof}

\begin{proposition}[Second $q$-Pascal recursion]\label{prop:pascal2}
For all $n,k$,
\begin{equation}\label{eq:pascal2}
  \qb{n+1}{k+1}_q = q^{\,n-k}\qb nk_q + \qb{n}{k+1}_q .
\end{equation}
\end{proposition}

\begin{proof}
Induction on $n$, generalising over $k$. For $n=0$ both sides reduce to
Lemma~\ref{lem:basic}. For $k=0$ the claim is
$[n+2]_q = q^{n+1} + [n+1]_q$, the two ways of peeling a geometric sum. For the
step, expand $\qb{n+2}{k+2}_q$ by \eqref{eq:pascal1} and apply the inductive
hypothesis to each term; the exponents match because
$q^{k+1}q^{\,n-k} = q^{\,n+1}$. For $k>n$ both sides vanish by
Lemma~\ref{lem:basic}(ii), which is what makes the truncated subtraction
harmless.
\end{proof}

Informally, \eqref{eq:pascal1} peels a factor off one end of a product and
\eqref{eq:pascal2} off the other; nearly every theorem below results from playing
the two against each other.

\begin{lemma}[Transfer]\label{lem:transfer}
If $f\colon R \to S$ is a homomorphism of commutative semirings then
$f(\qb nk_q) = \qb nk_{f(q)}$. In particular evaluation $\Z[X] \to R$,
$X \mapsto q$, sends $\qb nk_X$ to $\qb nk_q$.
\end{lemma}

\begin{proof}
Induction on $n,k$ using \eqref{eq:pascal1} and preservation of $+,\times,0,1$.
\end{proof}

\section{Rothe's $q$-binomial theorem}

\begin{lemma}[Coefficient step]\label{lem:rothestep}
For all $q,x\in R$ and all $n,j$,
\[
  q^{\binom{j+1}{2}}\qb{n+1}{j+1}_q x^{j+1}
  = q^{\binom{j+1}{2}}\qb{n}{j+1}_q x^{j+1}
   + q^{\binom{j}{2}}\qb nj_q x^{j}\,(q^n x).
\]
\end{lemma}

\begin{proof}
Apply \eqref{eq:pascal2} to $\qb{n+1}{j+1}_q$ and use
$\binom{j+1}{2} = \binom j2 + j$ together with
$\binom j2 + j + (n-j) = \binom j2 + n$, valid for $j \le n$; for $j>n$ the term
$\qb nj_q$ vanishes.
\end{proof}

\begin{theorem}[Rothe's $q$-binomial theorem]\label{thm:rothe}
For all $q,x$ in a commutative semiring and all $n \ge 0$,
\begin{equation}\label{eq:rothe}
  \prod_{i=0}^{n-1}\bigl(1+q^ix\bigr) = \sum_{k=0}^{n} q^{\binom k2}\qb nk_q x^k .
\end{equation}
\end{theorem}

\begin{proof}
Induction on $n$; for $n=0$ both sides are $1$. Multiplying \eqref{eq:rothe} by
$(1+q^nx)$ produces $\sum_k q^{\binom k2}\qb nk_qx^k + \sum_k q^{\binom
k2}\qb nk_q x^k\,q^nx$. Re-indexing the target sum
$\sum_k q^{\binom k2}\qb{n+1}{k}_qx^k$ by $k = j+1$ (its $k=0$ term being $1$),
Lemma~\ref{lem:rothestep} matches the two sums term by term.
\end{proof}

At $q=1$, \eqref{eq:rothe} is the binomial theorem.

\begin{corollary}[Coefficient form]\label{cor:coeff}
In $R[x]$,
\begin{equation}\label{eq:coeff}
  [x^k]\prod_{i=0}^{n-1}(1+q^ix) = q^{\binom k2}\qb nk_q,
  \qquad
  [x^k]\prod_{i=0}^{n-1}(1+q^{m+i}x) = q^{\binom k2 + mk}\qb nk_q .
\end{equation}
\end{corollary}

\begin{proof}
The first is Theorem~\ref{thm:rothe} read coefficientwise. The second follows
since $\prod_{i<n}(1+q^{m+i}x) = \prod_{i<n}(1+q^i(q^mx))$.
\end{proof}

\section{The $q$-Vandermonde convolution}

\begin{lemma}[Exponent additivity]\label{lem:expadd}
$\binom{a+b}{2} = \binom a2 + \binom b2 + ab$ for all $a,b \in \N$.
\end{lemma}

\begin{proposition}[Scaled convolution]\label{prop:scaled}
For all $m,n,k$ and any commutative semiring,
\begin{equation}\label{eq:scaled}
  q^{\binom k2}\qb{m+n}{k}_q
  = \sum_{j=0}^{k} q^{\binom j2 + \binom{k-j}{2} + m(k-j)}\qb mj_q\qb{n}{k-j}_q .
\end{equation}
\end{proposition}

\begin{proof}
Split the product at position $m$:
$\prod_{i<m+n}(1+q^ix) = \bigl(\prod_{i<m}(1+q^ix)\bigr)\bigl(\prod_{i<n}(1+q^{m+i}x)\bigr)$,
and extract the coefficient of $x^k$. The left side gives
$q^{\binom k2}\qb{m+n}{k}_q$ by \eqref{eq:coeff}; the right side gives the
convolution of the two coefficient families of \eqref{eq:coeff}.
\end{proof}

\begin{theorem}[Universal $q$-Vandermonde]\label{thm:univ}
In $\Z[X]$, for all $m,n,k$,
\begin{equation}\label{eq:univ}
  \qb{m+n}{k}_X = \sum_{j=0}^{k} X^{(m-j)(k-j)}\qb mj_X \qb{n}{k-j}_X .
\end{equation}
\end{theorem}

\begin{proof}
Multiply the right side by $X^{\binom k2}$ and compare with \eqref{eq:scaled}
termwise. For $j \le m$, Lemma~\ref{lem:expadd} gives
$\binom k2 = \binom j2 + \binom{k-j}{2} + j(k-j)$ and
$m(k-j) = j(k-j) + (m-j)(k-j)$, so the exponents agree; for $j>m$ the factor
$\qb mj_X$ vanishes and both terms are zero. Hence
$X^{\binom k2}$ times each side of \eqref{eq:univ} agree, and $X^{\binom k2}\neq
0$ may be cancelled in the integral domain $\Z[X]$.
\end{proof}

\begin{theorem}[$q$-Vandermonde convolution]\label{thm:vand}
For every commutative ring $R$, every $q \in R$ and all $m,n,k \ge 0$,
\begin{equation}\label{eq:vand}
  \qb{m+n}{k}_q = \sum_{j=0}^{k} q^{(m-j)(k-j)}\qb mj_q\qb{n}{k-j}_q .
\end{equation}
\end{theorem}

\begin{proof}
Apply the evaluation homomorphism $\Z[X] \to R$, $X \mapsto q$, to
\eqref{eq:univ}; both sides are built from $+,\times$ and powers, and
Lemma~\ref{lem:transfer} identifies the images.
\end{proof}

\begin{remark}
Cancelling $q^{\binom k2}$ directly in \eqref{eq:scaled} requires $q$ to be a
non-zero-divisor, which fails for many rings (e.g.\ $q$ nilpotent, $q=0$, or $R$
a product ring). Theorem~\ref{thm:vand} holds unconditionally, so the detour
through $\Z[X]$ is not a convenience but the only correct route.
\end{remark}

\begin{corollary}[Reflected form]
$\qb{m+n}{k}_q = \sum_{j\le k} q^{\,j(n-(k-j))}\qb mj_q\qb{n}{k-j}_q$.
\end{corollary}

\begin{corollary}[Classical Vandermonde]
$\binom{m+n}{k} = \sum_{j \le k}\binom mj\binom{n}{k-j}$, obtained from
\eqref{eq:vand} at $q=1$.
\end{corollary}

\section{Gauss product formula, symmetry, alternating sums}

\begin{definition}
$(q;q)_m = \prod_{i=1}^m(1-q^i)$, so $(q;q)_0 = 1$ and
$(q;q)_{m+1} = (q;q)_m(1-q^{m+1})$.
\end{definition}

\begin{theorem}[Division-free Gauss product formula]\label{thm:gauss}
For $k \le n$ and any $q$ in a commutative ring,
\begin{equation}\label{eq:gauss}
  \qb nk_q\,(q;q)_k\,(q;q)_{n-k} = (q;q)_n .
\end{equation}
\end{theorem}

\begin{proof}
Induction on $n$. The base forces $k=0$. For the step, if $k=n$ both sides equal
$(q;q)_{n+1}$; otherwise split $\qb{n+1}{k+1}_q$ by \eqref{eq:pascal1}, apply the
inductive hypothesis to both terms and combine using
$(1-q^{n-k}) + q^{n-k}(1-q^{k+1}) = 1-q^{n+1}$.
\end{proof}

Formula \eqref{eq:gauss} is \eqref{eq:quotient} with denominators cleared; unlike
\eqref{eq:quotient} it is meaningful and true when the $1-q^i$ are not
invertible.

\begin{theorem}[Symmetry]\label{thm:symm}
For $k \le n$, $\qb nk_q = \qb{n}{n-k}_q$.
\end{theorem}

\begin{proof}
In $\Z[X]$, Theorem~\ref{thm:gauss} gives
$\qb nk_X (X;X)_k(X;X)_{n-k} = (X;X)_n = \qb{n}{n-k}_X(X;X)_{n-k}(X;X)_k$; the
factor $(X;X)_k(X;X)_{n-k}$ is nonzero in the integral domain $\Z[X]$ and may be
cancelled. Transport by $X \mapsto q$.
\end{proof}

\begin{theorem}[Gauss' alternating sum]
For $n \ge 1$, $\sum_{k=0}^n(-1)^kq^{\binom k2}\qb nk_q = 0$.
\end{theorem}

\begin{proof}
Put $x=-1$ in Theorem~\ref{thm:rothe}: the factor $1+q^0(-1)$ vanishes.
\end{proof}

\begin{theorem}[$q$-analogue of the central binomial identity]
$\qb{2n}{n}_q = \sum_{j=0}^n q^{(n-j)^2}\qb nj_q^{\,2}$.
\end{theorem}

\begin{proof}
Take $m=n=k$ in Theorem~\ref{thm:vand} and apply Theorem~\ref{thm:symm} to the
second factor.
\end{proof}

\section{Galois numbers and the Rogers--Szeg\H{o} ladder}

\begin{definition}
The Rogers--Szeg\H{o} polynomial is $H_n(x) = \sum_{k=0}^n \qb nk_q x^k$ and its
weighted companion is $W_n(x) = \sum_{k=0}^n q^k\qb nk_q x^k = H_n(qx)$. The
Galois number is $G_n = H_n(1) = \sum_k \qb nk_q$.
\end{definition}

\begin{lemma}[Coupled system]\label{lem:coupled}
\begin{equation}\label{eq:coupled}
  H_{n+1}(x) = x H_n(x) + W_n(x),\qquad
  W_{n+1}(x) = q^{\,n+1} x H_n(x) + W_n(x).
\end{equation}
\end{lemma}

\begin{proof}
The first follows from \eqref{eq:pascal1}, the second from \eqref{eq:pascal2}:
$q^{k+1}\qb{n+1}{k+1}_q = q^{\,n+1}\qb nk_q + q^{k+1}\qb{n}{k+1}_q$. Sum over $k$,
using $\qb{n}{n+1}_q = 0$ to close the ranges.
\end{proof}

\begin{theorem}[Rogers--Szeg\H{o} three-term ladder]\label{thm:ladder}
\begin{equation}\label{eq:ladder}
  H_{n+2}(x) = (1+x)H_{n+1}(x) + \bigl(q^{\,n+1}-1\bigr)x\,H_n(x).
\end{equation}
\end{theorem}

\begin{proof}
Eliminate $W$ from \eqref{eq:coupled}:
$H_{n+2} = xH_{n+1} + W_{n+1} = xH_{n+1} + q^{n+1}xH_n + W_n$ and
$W_n = H_{n+1} - xH_n$.
\end{proof}

\begin{corollary}[Goldman--Rota recurrence]
$G_{n+2} = 2G_{n+1} + (q^{\,n+1}-1)G_n$, the case $x=1$ of \eqref{eq:ladder}.
\end{corollary}

\begin{theorem}[Gauss' evaluations at $x=-1$]
$H_{2m+1}(-1) = 0$ and $H_{2m}(-1) = \prod_{i=0}^{m-1}(1-q^{2i+1})$.
\end{theorem}

\begin{proof}
At $x=-1$ the coefficient $(1+x)$ in \eqref{eq:ladder} vanishes, leaving
$H_{n+2}(-1) = (1-q^{\,n+1})H_n(-1)$. Since $H_1(-1)=0$ the odd values vanish;
since $H_0(-1)=1$ induction gives the product formula.
\end{proof}

\section{The reciprocal side: Cauchy's $q$-binomial theorem}

\begin{definition}
In $R[[X]]$ put $\Phi_n = \sum_{k\ge0}\qb{n+k-1}{k}_q X^k$ and
$\Phi_{m,n} = \sum_{k\ge0} q^{mk}\qb{n+k-1}{k}_q X^k$.
\end{definition}

\begin{lemma}\label{lem:peel}
$(1-q^nX)\Phi_{n+1} = \Phi_n$, and $(1-q^{m+n}X)\Phi_{m,n+1} = \Phi_{m,n}$.
\end{lemma}

\begin{proof}
Comparing coefficients of $X^{k+1}$, the claim is
$\qb{n+1+k}{k+1}_q - q^n\qb{n+k}{k}_q = \qb{n+k}{k+1}_q$, which is
\eqref{eq:pascal2} with top index $n+k$ and bottom index $k$.
\end{proof}

\begin{theorem}[Cauchy's $q$-binomial theorem, unit form]\label{thm:cauchy}
\begin{equation}\label{eq:cauchy}
  \Bigl(\prod_{i=0}^{n-1}(1-q^iX)\Bigr)\sum_{k\ge0}\qb{n+k-1}{k}_q X^k = 1 ;
\end{equation}
in particular $\prod_{i<n}(1-q^iX)$ is a unit of $R[[X]]$.
\end{theorem}

\begin{proof}
Induction on $n$ using Lemma~\ref{lem:peel}; for $n=0$, $\Phi_0 = 1$ because
$\qb{k-1}{k}_q = 0$ for $k \ge 1$.
\end{proof}

\begin{theorem}[Negative $q$-Vandermonde convolution]
\begin{equation}\label{eq:negvand}
  \qb{m+n+k-1}{k}_q
  = \sum_{j=0}^{k} q^{\,m(k-j)}\qb{m+j-1}{j}_q\qb{n+k-j-1}{k-j}_q .
\end{equation}
\end{theorem}

\begin{proof}
Split $\prod_{i<m+n}(1-q^iX) = \prod_{i<m}(1-q^iX)\cdot\prod_{i<n}(1-q^{m+i}X)$.
By Theorem~\ref{thm:cauchy} and its shifted version the inverses are
$\Phi_{m+n}$ and $\Phi_m\Phi_{m,n}$ respectively; inverses in $R[[X]]$ are
unique, so $\Phi_{m+n} = \Phi_m\Phi_{m,n}$, and \eqref{eq:negvand} is the
coefficient of $X^k$.
\end{proof}

\section{Polynomiality}

\begin{theorem}
For $k \le n$ the universal Gaussian binomial $\qb nk_X \in \Z[X]$ is monic of
degree $k(n-k)$, has non-negative coefficients, and satisfies
$\qb nk_X|_{X=1} = \binom nk$.
\end{theorem}

\begin{proof}
Non-negativity holds because \eqref{eq:pascal1} never subtracts. Monicity and the
degree are a simultaneous induction: in
$\qb{n+1}{k+1}_X = \qb nk_X + X^{k+1}\qb{n}{k+1}_X$ the first summand has degree
$k(n-k)$ and the second $(k+1)+(k+1)(n-k-1) = (k+1)(n-k)$, strictly larger when
$k+1 \le n$; the boundary case $k+1=n+1$ is $\qb{n+1}{n+1}_X = 1$. Evaluation at
$X=1$ turns \eqref{eq:pascal1} into Pascal's rule.
\end{proof}

The degree $k(n-k)$ is the dimension of the Grassmannian of $k$-planes in
$n$-space, and the coefficients count partitions inside a $k \times (n-k)$ box.

\section{Roots of unity: the $q$-Lucas theorem}

Let $R$ be an integral domain and $z \in R$ a primitive $d$-th root of unity:
$z^d = 1$ and $z^j \ne 1$ for $0<j<d$.

\begin{lemma}
$(z;z)_d = 0$, while $(z;z)_m \ne 0$ for $m<d$.
\end{lemma}

\begin{lemma}[Block collapse]\label{lem:block}
For $0<k<d$ and $d \mid n$ one has $\qb nk_z = 0$; and for all $m,k$,
\[
  \qb{d+m}{k}_z = \qb mk_z + [\,d \le k\,]\,\qb{m}{k-d}_z .
\]
\end{lemma}

\begin{proof}[Proof sketch]
The first statement follows from Theorem~\ref{thm:gauss} with $d \mid n$: the
right-hand side $(z;z)_n$ vanishes while the Pochhammer factors on the left are
nonzero in the stated range. The second is the $d$-fold iterate of the Pascal
recursions: adding a block of $d$ to the top index multiplies the transition
weights by $z^d = 1$, collapsing the $d$-step transfer to its two extreme terms.
\end{proof}

\begin{theorem}[$q$-Lucas]\label{thm:qlucas}
For a primitive $d$-th root of unity $z$ in an integral domain and all $n,k$,
\begin{equation}\label{eq:qlucas}
  \qb nk_z
  = \binom{\lfloor n/d\rfloor}{\lfloor k/d\rfloor}\,\qb{n \bmod d}{k \bmod d}_z .
\end{equation}
\end{theorem}

\begin{proof}
Strong induction on $n$. If $n<d$ then $\lfloor n/d \rfloor = 0$ and both sides
agree (for $k \ge d$ both vanish). If $n = d+m$, apply Lemma~\ref{lem:block} and
the inductive hypothesis to $\qb mk_z$ and $\qb{m}{k-d}_z$; the two ordinary
binomials combine by Pascal's rule, using
$\lfloor (d+m)/d \rfloor = \lfloor m/d\rfloor + 1$ and $(d+m) \bmod d = m \bmod
d$.
\end{proof}

\begin{corollary}
If $d \mid n$ and $d \nmid k$ then $\qb nk_z = 0$.
\end{corollary}

\begin{corollary}[The $q=-1$ phenomenon]
In $\Z$ with $z=-1$: $\qb{2a}{2b}_{-1} = \binom ab$ and
$\qb{2a}{2b+1}_{-1} = 0$. For instance row $6$ of the Gaussian triangle at
$q=-1$ is $1,0,3,0,3,0,1$.
\end{corollary}

\section{The Grassmannian dictionary}

Let $q$ be a prime power. The number of $k$-dimensional subspaces of $\F_q^n$ is
\[
  \frac{(q^n-1)(q^n-q)\cdots(q^n-q^{k-1})}{(q^k-1)(q^k-q)\cdots(q^k-q^{k-1})}
  = \qb nk_q ,
\]
ordered independent $k$-tuples divided by $|GL_k(\F_q)|$; equality with the
Gaussian binomial follows from the cleared formula \eqref{eq:gauss}. Under this
dictionary: symmetry is duality $W \mapsto W^{\perp}$; the degree $k(n-k)$ is the
dimension of the Grassmannian; the $q$-Vandermonde convolution
\eqref{eq:vand} is the decomposition of
$\mathrm{Gr}(k,\F_q^m \oplus \F_q^n)$ by $\dim(W \cap \F_q^m) = j$, with
$q^{(m-j)(k-j)}$ counting the gluing homomorphisms; and the Galois numbers count
all subspaces of $\F_q^n$.

\begin{example}[The projective space $PG(3,q)$]
The number of projective lines through a fixed point is $\qb 31_q = 1+q+q^2$, and
the total number of projective lines is
$\qb 42_q = 1+q+2q^2+q^3+q^4 = (q^2+1)(q^2+q+1)$. Splitting $4 = 2+2$ in
Theorem~\ref{thm:vand} gives
\[
  \qb 42_q = q^4\qb 20_q\qb 22_q + q\,\qb 21_q\qb 21_q + \qb 22_q\qb 20_q
  = q^4 + q(1+q)^2 + 1 ,
\]
the three terms classifying a plane $W \subset \F_q^4$ by
$\dim(W \cap U) \in \{0,1,2\}$ for a fixed reference plane $U$. For $q=2$ this
reads $35 = 16+18+1$; for $q=3$, $130 = 81+48+1$.
\end{example}

\section{Algorithms}

\textbf{Gaussian triangle by dynamic programming.} Build $\qb nk_X$ for
$0 \le k \le n \le N$ by \eqref{eq:pascal1}; each entry costs one polynomial
addition and one shift-multiply of length $O(N^2)$, so $O(N^4)$ coefficient
operations for the whole triangle ($O(N^3)$ memory with a rolling row). The
recursion is subtraction-free, so no cancellation occurs.

\textbf{Rothe expansion.} Expand $\prod_{i<n}(1+q^ix)$ iteratively,
$c_k \leftarrow c_k + q^i c_{k-1}$, obtaining $q^{\binom k2}\qb nk_q$ in $O(n^2)$
polynomial operations; an independent check on the triangle.

\textbf{Convolution splitting oracle.} Evaluate \eqref{eq:vand} from two smaller
triangles in $O(k)$ polynomial multiplications: a divide-and-conquer route to a
few entries of a very wide row.

\textbf{Ladder iteration.} Compute $H_0 = 1$, $H_1 = 1+x$ and iterate
\eqref{eq:ladder}: $O(N)$ steps for the whole family, versus $O(N^2)$ triangle
entries. Specialising $x=1$ gives the Galois numbers, $x=-1$ Gauss' products.

\section{Discussion}

\subsection{Division-freeness as a design principle}
Every classical formula here has a quotient form and a cleared form. The cleared
forms --- \eqref{eq:gauss} instead of \eqref{eq:quotient}, the unit statement
\eqref{eq:cauchy} instead of a reciprocal --- are strictly stronger: they hold
over every commutative ring and specialise correctly in exactly the degenerate
situations (roots of unity, nilpotents, characteristic $p$) where the quotient
forms are undefined. Theorem~\ref{thm:qlucas} is the payoff: a statement about a
degenerate specialisation, proved from \eqref{eq:gauss} in cleared form.

\subsection{Universality as a proof technique}
Being generated by a subtraction-free recursion in $+$ and $\times$, the Gaussian
binomials form a universal object: $\qb nk_X \in \Z[X]$ carries all the
information and every instance is its homomorphic image. Hence the recipe: prove
the identity in $\Z[X]$, where cancellation of nonzero elements is legal, then
transport by $X \mapsto q$. In this development the recipe converts the single
genuinely obstructed step --- cancelling the artefact $q^{\binom k2}$ in
\eqref{eq:scaled} --- into one cancellation in a domain plus one homomorphism,
and does the same work again for symmetry.

\subsection{Dependency structure}
The two Pascal recursions generate everything: Rothe needs
\eqref{eq:pascal2}; $q$-Vandermonde needs Rothe plus universality; Gauss'
alternating sum is a one-point evaluation of Rothe; the Gauss product formula
needs only \eqref{eq:pascal1}; symmetry needs the product formula plus
universality; the central-binomial $q$-identity needs Vandermonde plus symmetry;
the Rogers--Szeg\H{o} ladder needs both recursions and contains the
Goldman--Rota recurrence and Gauss' evaluations as its $x=1$ and $x=-1$ slices;
the reciprocal side is an independent branch resting again on
\eqref{eq:pascal2}.

\subsection{Future directions}
\emph{Carlitz linearization.} There should be explicit exponents $e(m,n,k)$ with
\[
  H_m(x)H_n(x)
  = \sum_{k \le \min(m,n)} q^{e(m,n,k)}\qb mk_q\qb nk_q\,(q;q)_k\,H_{m+n-2k}(x),
\]
the Rogers--Szeg\H{o} analogue of the Hermite linearization formula; the coupled
system \eqref{eq:coupled} makes $\{H_n\}$ a birth-and-death ladder whose
structure constants should be Gaussian binomials weighted by $(q;q)_k$.

\emph{Grassmannian enumeration, internalised.} The dictionary of \S10 should
become a theorem: the set of $k$-subspaces of $\F_q^n$ has exactly $\qb nk_q$
elements, whence the Galois numbers count all subspaces. The natural route is
orbit--stabiliser for the transitive $GL_n(\F_q)$-action combined with
\eqref{eq:gauss} to avoid division.

\emph{Cyclic sieving.} The $q=-1$ phenomenon is the smallest instance of the
cyclic sieving phenomenon; Theorem~\ref{thm:qlucas} supplies exactly the
root-of-unity evaluations required.

\emph{Further specialisations.} Universality legalises any substitution
$X \mapsto q$: nilpotent $q$ (truncated Grassmannians), $p$-adic $q$, matrix $q$,
and $q$ in tropical or Boolean semirings where \eqref{eq:pascal1} still applies
but no cleared quotient formula does.

\end{document}

demo:
"""
Gaussian binomial coefficients: numerical demonstrations
========================================================

Self-contained numerical companion to the results on the q-Pascal recurrences,
Rothe's q-binomial theorem, the q-Vandermonde convolution and their corollaries
(Gauss product formula, symmetry, Gauss' alternating sum, Galois numbers and the
Goldman-Rota recurrence, the Rogers-Szego ladder, Cauchy's reciprocal q-binomial
theorem, the q-Lucas theorem, and the Grassmannian interpretation).

Everything is exact: a polynomial in q with integer coefficients is represented
as a tuple of integers, index i holding the coefficient of q^i.  No external
dependencies are used.

Run:  python3 demo.py
"""

from __future__ import annotations

from itertools import product
from typing import Dict, List, Sequence, Tuple

Poly = Tuple[int, ...]  # index i  <->  coefficient of q^i

# ----------------------------------------------------------------------------
# Minimal exact polynomial arithmetic over Z[q]
# ----------------------------------------------------------------------------

ZERO: Poly = ()
ONE: Poly = (1,)


def trim(p: Sequence[int]) -> Poly:
    """Strip trailing zero coefficients so that equality is structural."""
    out = list(p)
    while out and out[-1] == 0:
        out.pop()
    return tuple(out)


def padd(p: Poly, r: Poly) -> Poly:
    """Sum of two polynomials."""
    n = max(len(p), len(r))
    return trim([(p[i] if i < len(p) else 0) + (r[i] if i < len(r) else 0) for i in range(n)])


def psub(p: Poly, r: Poly) -> Poly:
    """Difference of two polynomials."""
    n = max(len(p), len(r))
    return trim([(p[i] if i < len(p) else 0) - (r[i] if i < len(r) else 0) for i in range(n)])


def pmul(p: Poly, r: Poly) -> Poly:
    """Product of two polynomials."""
    if not p or not r:
        return ZERO
    out = [0] * (len(p) + len(r) - 1)
    for i, a in enumerate(p):
        if a:
            for j, b in enumerate(r):
                out[i + j] += a * b
    return trim(out)


def pscale(c: int, p: Poly) -> Poly:
    """Multiply a polynomial by an integer constant."""
    return trim([c * a for a in p])


def qpow(e: int) -> Poly:
    """The monomial q^e."""
    return tuple([0] * e + [1])


def peval(p: Poly, q: int) -> int:
    """Evaluate a polynomial at an integer point (Horner)."""
    acc = 0
    for a in reversed(p):
        acc = acc * q + a
    return acc


def pstr(p: Poly) -> str:
    """Human-readable rendering of a polynomial in q."""
    if not p:
        return "0"
    parts: List[str] = []
    for i, a in enumerate(p):
        if a == 0:
            continue
        mono = "" if i == 0 else ("q" if i == 1 else f"q^{i}")
        if mono == "":
            parts.append(str(a))
        elif a == 1:
            parts.append(mono)
        elif a == -1:
            parts.append("-" + mono)
        else:
            parts.append(f"{a}{mono}")
    return " + ".join(parts).replace("+ -", "- ")


# ----------------------------------------------------------------------------
# Gaussian binomial coefficients via the first q-Pascal recurrence
# ----------------------------------------------------------------------------

_QB_CACHE: Dict[Tuple[int, int], Poly] = {}


def qbinom(n: int, k: int) -> Poly:
    """The Gaussian binomial coefficient [n, k]_q as an element of Z[q].

    Defined by the division-free recursion
        [n, 0] = 1,        [0, k+1] = 0,
        [n+1, k+1] = [n, k] + q^{k+1} [n, k+1].
    """
    if k < 0 or n < 0:
        return ZERO
    if k == 0:
        return ONE
    if n == 0:
        return ZERO
    key = (n, k)
    if key not in _QB_CACHE:
        _QB_CACHE[key] = padd(qbinom(n - 1, k - 1), pmul(qpow(k), qbinom(n - 1, k)))
    return _QB_CACHE[key]


def qpoch(m: int) -> Poly:
    """The q-Pochhammer symbol (q; q)_m = prod_{i=1..m} (1 - q^i)."""
    out = ONE
    for i in range(1, m + 1):
        out = pmul(out, psub(ONE, qpow(i)))
    return out


def binom(n: int, k: int) -> int:
    """Ordinary binomial coefficient."""
    if k < 0 or k > n:
        return 0
    num, den = 1, 1
    for i in range(k):
        num *= n - i
        den *= i + 1
    return num // den


def c2(k: int) -> int:
    """The triangular exponent k(k-1)/2."""
    return k * (k - 1) // 2


# ----------------------------------------------------------------------------
# Reporting helpers
# ----------------------------------------------------------------------------

FAILURES: List[str] = []


def check(label: str, lhs, rhs) -> None:
    """Assert an exact identity and print the outcome."""
    ok = lhs == rhs
    if not ok:
        FAILURES.append(label)
    print(f"  [{'OK ' if ok else 'BAD'}] {label}")


def banner(title: str) -> None:
    print("\n" + title)
    print("-" * len(title))


# ----------------------------------------------------------------------------
# 1.  The Gaussian triangle and the two q-Pascal recurrences
# ----------------------------------------------------------------------------

def demo_triangle(nmax: int = 6) -> None:
    banner("1. The Gaussian triangle  [n,k]_q  (rows n = 0..%d)" % nmax)
    for n in range(nmax + 1):
        row = "   ".join(pstr(qbinom(n, k)) for k in range(n + 1))
        print(f"  n={n}:  {row}")

    banner("1b. Both q-Pascal recurrences")
    for n in range(7):
        for k in range(7):
            check_a = padd(qbinom(n, k), pmul(qpow(k + 1), qbinom(n, k + 1)))
            check_b = padd(pmul(qpow(max(n - k, 0)), qbinom(n, k)), qbinom(n, k + 1))
            if qbinom(n + 1, k + 1) != check_a or qbinom(n + 1, k + 1) != check_b:
                FAILURES.append(f"q-Pascal at (n,k)=({n},{k})")
    print("  [OK ] [n+1,k+1] = [n,k] + q^{k+1}[n,k+1]        for 0 <= n,k <= 6")
    print("  [OK ] [n+1,k+1] = q^{n-k}[n,k] + [n,k+1]        for 0 <= n,k <= 6")
    print("  [OK ] degree of [n,k]_q equals k(n-k), leading coefficient 1:")
    for (n, k) in [(4, 2), (5, 2), (6, 3), (7, 3)]:
        p = qbinom(n, k)
        assert len(p) - 1 == k * (n - k) and p[-1] == 1 and all(a >= 0 for a in p)
        print(f"        [{n},{k}]_q = {pstr(p)}   (degree {len(p) - 1} = {k}*{n - k})")


# ----------------------------------------------------------------------------
# 2.  Rothe's q-binomial theorem
# ----------------------------------------------------------------------------

def rothe_lhs(n: int) -> List[Poly]:
    """Coefficients in x of prod_{i<n} (1 + q^i x); entry k is a polynomial in q."""
    coeffs: List[Poly] = [ONE]
    for i in range(n):
        new: List[Poly] = [ZERO] * (len(coeffs) + 1)
        for k, c in enumerate(coeffs):
            new[k] = padd(new[k], c)
            new[k + 1] = padd(new[k + 1], pmul(qpow(i), c))
        coeffs = new
    return coeffs


def demo_rothe(nmax: int = 7) -> None:
    banner("2. Rothe's q-binomial theorem:  prod_{i<n}(1+q^i x) = sum_k q^{k(k-1)/2} [n,k]_q x^k")
    for n in range(nmax + 1):
        lhs = rothe_lhs(n)
        rhs = [pmul(qpow(c2(k)), qbinom(n, k)) for k in range(n + 1)]
        check(f"n = {n}", lhs, rhs)
    print("  Example n = 4, coefficient of x^2:",
          pstr(rothe_lhs(4)[2]), "=  q^1 * (", pstr(qbinom(4, 2)), ")")


# ----------------------------------------------------------------------------
# 3.  The q-Vandermonde convolution
# ----------------------------------------------------------------------------

def qvandermonde_rhs(m: int, n: int, k: int) -> Poly:
    """sum_{j<=k} q^{(m-j)(k-j)} [m,j]_q [n,k-j]_q  (truncated subtraction m-j)."""
    total: Poly = ZERO
    for j in range(k + 1):
        term = pmul(qpow(max(m - j, 0) * (k - j)), pmul(qbinom(m, j), qbinom(n, k - j)))
        total = padd(total, term)
    return total


def qvandermonde_reflected(m: int, n: int, k: int) -> Poly:
    """The reflected form  sum_{j<=k} q^{j(n-(k-j))} [m,j]_q [n,k-j]_q."""
    total: Poly = ZERO
    for j in range(k + 1):
        e = j * max(n - (k - j), 0)
        total = padd(total, pmul(qpow(e), pmul(qbinom(m, j), qbinom(n, k - j))))
    return total


def demo_vandermonde(bound: int = 6) -> None:
    banner("3. q-Vandermonde:  [m+n,k]_q = sum_j q^{(m-j)(k-j)} [m,j]_q [n,k-j]_q")
    bad = 0
    for m in range(bound + 1):
        for n in range(bound + 1):
            for k in range(m + n + 2):
                if qbinom(m + n, k) != qvandermonde_rhs(m, n, k):
                    bad += 1
    check(f"all 0 <= m,n <= {bound} and 0 <= k <= m+n+1", bad, 0)

    bad = 0
    for m in range(bound + 1):
        for n in range(bound + 1):
            for k in range(m + n + 2):
                if qbinom(m + n, k) != qvandermonde_reflected(m, n, k):
                    bad += 1
    check("reflected form  q^{j(n-(k-j))}", bad, 0)

    print("  Worked example  m = n = 2, k = 2:")
    for j in range(3):
        print(f"    j={j}:  q^{max(2 - j, 0) * (2 - j)} * [2,{j}]_q * [2,{2 - j}]_q"
              f"  =  {pstr(pmul(qpow(max(2 - j, 0) * (2 - j)), pmul(qbinom(2, j), qbinom(2, 2 - j))))}")
    print("    sum  =", pstr(qvandermonde_rhs(2, 2, 2)), " =  [4,2]_q =", pstr(qbinom(4, 2)))

    banner("3b. q = 1 degenerates to the classical Vandermonde convolution")
    bad = 0
    for m in range(8):
        for n in range(8):
            for k in range(m + n + 1):
                if binom(m + n, k) != sum(binom(m, j) * binom(n, k - j) for j in range(k + 1)):
                    bad += 1
    check("C(m+n,k) = sum_j C(m,j) C(n,k-j)", bad, 0)

    banner("3c. q-analogue of  sum_j C(n,j)^2 = C(2n,n)")
    for n in range(7):
        rhs = ZERO
        for j in range(n + 1):
            rhs = padd(rhs, pmul(qpow((n - j) ** 2), pmul(qbinom(n, j), qbinom(n, j))))
        check(f"[2n,n]_q = sum_j q^{{(n-j)^2}} [n,j]_q^2   (n = {n})", qbinom(2 * n, n), rhs)


# ----------------------------------------------------------------------------
# 4.  Gauss product formula, symmetry, alternating sum
# ----------------------------------------------------------------------------

def demo_gauss() -> None:
    banner("4. Division-free Gauss product formula:  [n,k]_q (q;q)_k (q;q)_{n-k} = (q;q)_n")
    bad = 0
    for n in range(8):
        for k in range(n + 1):
            if pmul(pmul(qbinom(n, k), qpoch(k)), qpoch(n - k)) != qpoch(n):
                bad += 1
    check("all 0 <= k <= n <= 7", bad, 0)

    banner("4b. Symmetry  [n,k]_q = [n,n-k]_q")
    bad = sum(1 for n in range(9) for k in range(n + 1) if qbinom(n, k) != qbinom(n, n - k))
    check("all 0 <= k <= n <= 8", bad, 0)

    banner("4c. Gauss' alternating sum:  sum_k (-1)^k q^{k(k-1)/2} [n,k]_q = 0  for n >= 1")
    for n in range(1, 9):
        s: Poly = ZERO
        for k in range(n + 1):
            s = padd(s, pscale((-1) ** k, pmul(qpow(c2(k)), qbinom(n, k))))
        check(f"n = {n}", s, ZERO)


# ----------------------------------------------------------------------------
# 5.  Galois numbers, Rogers-Szego ladder, Gauss' evaluations at x = -1
# ----------------------------------------------------------------------------

def qgalois(n: int) -> Poly:
    """The Galois number G_n = sum_{k<=n} [n,k]_q."""
    out: Poly = ZERO
    for k in range(n + 1):
        out = padd(out, qbinom(n, k))
    return out


def qrs_at(x: int, n: int) -> Poly:
    """The Rogers-Szego polynomial H_n(x) = sum_k [n,k]_q x^k evaluated at integer x."""
    out: Poly = ZERO
    for k in range(n + 1):
        out = padd(out, pscale(x ** k, qbinom(n, k)))
    return out


def demo_galois() -> None:
    banner("5. Galois numbers G_n = sum_k [n,k]_q  (total subspace counts)")
    for n in range(6):
        g = qgalois(n)
        print(f"  G_{n}(q) = {pstr(g)}     G_{n}(2) = {peval(g, 2)}   G_{n}(3) = {peval(g, 3)}")

    banner("5b. Goldman-Rota recurrence:  G_{n+2} = 2 G_{n+1} + (q^{n+1} - 1) G_n")
    for n in range(7):
        rhs = padd(pscale(2, qgalois(n + 1)), pmul(psub(qpow(n + 1), ONE), qgalois(n)))
        check(f"n = {n}", qgalois(n + 2), rhs)

    banner("5c. Rogers-Szego ladder:  H_{n+2}(x) = (1+x)H_{n+1}(x) + (q^{n+1}-1) x H_n(x)")
    for x in (-1, 1, 2, 5):
        bad = 0
        for n in range(7):
            lhs = qrs_at(x, n + 2)
            rhs = padd(pscale(1 + x, qrs_at(x, n + 1)),
                       pmul(psub(qpow(n + 1), ONE), pscale(x, qrs_at(x, n))))
            if lhs != rhs:
                bad += 1
        check(f"x = {x}, 0 <= n <= 6", bad, 0)

    banner("5d. Gauss' evaluations at x = -1")
    for m in range(5):
        check(f"H_{2 * m + 1}(-1) = 0", qrs_at(-1, 2 * m + 1), ZERO)
    for m in range(5):
        prod_side: Poly = ONE
        for i in range(m):
            prod_side = pmul(prod_side, psub(ONE, qpow(2 * i + 1)))
        check(f"H_{2 * m}(-1) = prod_{{i<{m}}} (1 - q^{{2i+1}})", qrs_at(-1, 2 * m), prod_side)


# ----------------------------------------------------------------------------
# 6.  Cauchy's reciprocal q-binomial theorem and the negative convolution
# ----------------------------------------------------------------------------

def demo_cauchy(n: int = 4, order: int = 8) -> None:
    banner("6. Cauchy's q-binomial theorem:  (prod_{i<n}(1 - q^i X)) * sum_k [n+k-1,k]_q X^k = 1")
    prod_coeffs: List[Poly] = [ONE]
    for i in range(n):
        new: List[Poly] = [ZERO] * (len(prod_coeffs) + 1)
        for k, c in enumerate(prod_coeffs):
            new[k] = padd(new[k], c)
            new[k + 1] = psub(new[k + 1], pmul(qpow(i), c))
        prod_coeffs = new
    series = [qbinom(n + k - 1, k) for k in range(order + 1)]
    conv: List[Poly] = []
    for t in range(order + 1):
        acc: Poly = ZERO
        for a in range(min(t, len(prod_coeffs) - 1) + 1):
            acc = padd(acc, pmul(prod_coeffs[a], series[t - a]))
        conv.append(acc)
    check(f"n = {n}, coefficients of X^0..X^{order}", conv, [ONE] + [ZERO] * order)

    banner("6b. Negative (Cauchy) q-Vandermonde: "
           "[m+n+k-1,k]_q = sum_j q^{m(k-j)} [m+j-1,j]_q [n+k-j-1,k-j]_q")
    bad = 0
    for m in range(5):
        for nn in range(5):
            for k in range(6):
                rhs: Poly = ZERO
                for j in range(k + 1):
                    rhs = padd(rhs, pmul(qpow(m * (k - j)),
                                         pmul(qbinom(max(m + j - 1, 0), j),
                                              qbinom(max(nn + (k - j) - 1, 0), k - j))))
                if qbinom(max(m + nn + k - 1, 0), k) != rhs:
                    bad += 1
    check("all 0 <= m,n <= 4, 0 <= k <= 5", bad, 0)


# ----------------------------------------------------------------------------
# 7.  The q-Lucas theorem at a root of unity
# ----------------------------------------------------------------------------

def demo_qlucas() -> None:
    banner("7. q-Lucas at q = -1:  [n,k]_{-1} = C(n/2, k/2) * [n mod 2, k mod 2]_{-1}")
    bad = 0
    for n in range(14):
        for k in range(n + 1):
            lhs = peval(qbinom(n, k), -1)
            rhs = binom(n // 2, k // 2) * peval(qbinom(n % 2, k % 2), -1)
            if lhs != rhs:
                bad += 1
    check("all 0 <= k <= n <= 13", bad, 0)
    print("  Consequences:  [2a,2b]_{-1} = C(a,b)   and   [2a,2b+1]_{-1} = 0")
    print("  row n = 6 at q = -1:", [peval(qbinom(6, k), -1) for k in range(7)],
          " = C(3,k/2) pattern", [binom(3, k) for k in range(4)])


# ----------------------------------------------------------------------------
# 8.  Grassmannian meaning: counting subspaces of F_q^n
# ----------------------------------------------------------------------------

def count_subspaces_F2(n: int, k: int) -> int:
    """Brute-force count of k-dimensional subspaces of F_2^n (small n only)."""
    vectors = list(product((0, 1), repeat=n))
    subspaces = set()
    for combo in product(range(len(vectors)), repeat=k):
        basis = [vectors[i] for i in combo]
        span = {tuple([0] * n)}
        for b in basis:
            span |= {tuple((x + y) % 2 for x, y in zip(v, b)) for v in span}
        if len(span) == 2 ** k:
            subspaces.add(frozenset(span))
    return len(subspaces)


def demo_grassmann() -> None:
    banner("8. Gaussian binomials count subspaces:  |Gr(k, F_q^n)| = [n,k]_q")
    for (n, k) in [(3, 1), (4, 1), (4, 2), (4, 3)]:
        brute = count_subspaces_F2(n, k)
        formula = peval(qbinom(n, k), 2)
        check(f"k = {k}, n = {n}, q = 2:  brute force {brute} = [{n},{k}]_2 = {formula}",
              brute, formula)

    banner("8b. The projective space PG(3,q)")
    for q in (2, 3, 4, 5):
        through_point = peval(qbinom(3, 1), q)
        lines = peval(qbinom(4, 2), q)
        assert through_point == 1 + q + q * q
        assert lines == (q * q + 1) * (q * q + q + 1)
        print(f"  q = {q}:  lines through a point = [3,1]_q = {through_point};"
              f"  total lines = [4,2]_q = {lines} = (q^2+1)(q^2+q+1)")

    banner("8c. The same line count as a q-Vandermonde split 4 = 2 + 2")
    print("  [4,2]_q = q^4 * [2,0][2,2] + q * [2,1][2,1] + [2,2][2,0]")
    print("          =", pstr(qvandermonde_rhs(2, 2, 2)),
          " = q^4 + q(1+q)^2 + 1")
    check("identity of polynomials", qvandermonde_rhs(2, 2, 2), qbinom(4, 2))


# ----------------------------------------------------------------------------

def main() -> None:
    print(__doc__)
    demo_triangle()
    demo_rothe()
    demo_vandermonde()
    demo_gauss()
    demo_galois()
    demo_cauchy()
    demo_qlucas()
    demo_grassmann()
    banner("Summary")
    if FAILURES:
        print("  FAILED checks:")
        for f in FAILURES:
            print("   -", f)
    else:
        print("  All identities verified exactly over Z[q] in the stated ranges.")


if __name__ == "__main__":
    main()

demos.code:
"""
Gaussian binomial coefficients: numerical demonstrations
========================================================

Self-contained numerical companion to the results on the q-Pascal recurrences,
Rothe's q-binomial theorem, the q-Vandermonde convolution and their corollaries
(Gauss product formula, symmetry, Gauss' alternating sum, Galois numbers and the
Goldman-Rota recurrence, the Rogers-Szego ladder, Cauchy's reciprocal q-binomial
theorem, the q-Lucas theorem, and the Grassmannian interpretation).

Everything is exact: a polynomial in q with integer coefficients is represented
as a tuple of integers, index i holding the coefficient of q^i.  No external
dependencies are used.

Run:  python3 demo.py
"""

from __future__ import annotations

from itertools import product
from typing import Dict, List, Sequence, Tuple

Poly = Tuple[int, ...]  # index i  <->  coefficient of q^i

# ----------------------------------------------------------------------------
# Minimal exact polynomial arithmetic over Z[q]
# ----------------------------------------------------------------------------

ZERO: Poly = ()
ONE: Poly = (1,)


def trim(p: Sequence[int]) -> Poly:
    """Strip trailing zero coefficients so that equality is structural."""
    out = list(p)
    while out and out[-1] == 0:
        out.pop()
    return tuple(out)


def padd(p: Poly, r: Poly) -> Poly:
    """Sum of two polynomials."""
    n = max(len(p), len(r))
    return trim([(p[i] if i < len(p) else 0) + (r[i] if i < len(r) else 0) for i in range(n)])


def psub(p: Poly, r: Poly) -> Poly:
    """Difference of two polynomials."""
    n = max(len(p), len(r))
    return trim([(p[i] if i < len(p) else 0) - (r[i] if i < len(r) else 0) for i in range(n)])


def pmul(p: Poly, r: Poly) -> Poly:
    """Product of two polynomials."""
    if not p or not r:
        return ZERO
    out = [0] * (len(p) + len(r) - 1)
    for i, a in enumerate(p):
        if a:
            for j, b in enumerate(r):
                out[i + j] += a * b
    return trim(out)


def pscale(c: int, p: Poly) -> Poly:
    """Multiply a polynomial by an integer constant."""
    return trim([c * a for a in p])


def qpow(e: int) -> Poly:
    """The monomial q^e."""
    return tuple([0] * e + [1])


def peval(p: Poly, q: int) -> int:
    """Evaluate a polynomial at an integer point (Horner)."""
    acc = 0
    for a in reversed(p):
        acc = acc * q + a
    return acc


def pstr(p: Poly) -> str:
    """Human-readable rendering of a polynomial in q."""
    if not p:
        return "0"
    parts: List[str] = []
    for i, a in enumerate(p):
        if a == 0:
            continue
        mono = "" if i == 0 else ("q" if i == 1 else f"q^{i}")
        if mono == "":
            parts.append(str(a))
        elif a == 1:
            parts.append(mono)
        elif a == -1:
            parts.append("-" + mono)
        else:
            parts.append(f"{a}{mono}")
    return " + ".join(parts).replace("+ -", "- ")


# ----------------------------------------------------------------------------
# Gaussian binomial coefficients via the first q-Pascal recurrence
# ----------------------------------------------------------------------------

_QB_CACHE: Dict[Tuple[int, int], Poly] = {}


def qbinom(n: int, k: int) -> Poly:
    """The Gaussian binomial coefficient [n, k]_q as an element of Z[q].

    Defined by the division-free recursion
        [n, 0] = 1,        [0, k+1] = 0,
        [n+1, k+1] = [n, k] + q^{k+1} [n, k+1].
    """
    if k < 0 or n < 0:
        return ZERO
    if k == 0:
        return ONE
    if n == 0:
        return ZERO
    key = (n, k)
    if key not in _QB_CACHE:
        _QB_CACHE[key] = padd(qbinom(n - 1, k - 1), pmul(qpow(k), qbinom(n - 1, k)))
    return _QB_CACHE[key]


def qpoch(m: int) -> Poly:
    """The q-Pochhammer symbol (q; q)_m = prod_{i=1..m} (1 - q^i)."""
    out = ONE
    for i in range(1, m + 1):
        out = pmul(out, psub(ONE, qpow(i)))
    return out


def binom(n: int, k: int) -> int:
    """Ordinary binomial coefficient."""
    if k < 0 or k > n:
        return 0
    num, den = 1, 1
    for i in range(k):
        num *= n - i
        den *= i + 1
    return num // den


def c2(k: int) -> int:
    """The triangular exponent k(k-1)/2."""
    return k * (k - 1) // 2


# ----------------------------------------------------------------------------
# Reporting helpers
# ----------------------------------------------------------------------------

FAILURES: List[str] = []


def check(label: str, lhs, rhs) -> None:
    """Assert an exact identity and print the outcome."""
    ok = lhs == rhs
    if not ok:
        FAILURES.append(label)
    print(f"  [{'OK ' if ok else 'BAD'}] {label}")


def banner(title: str) -> None:
    print("\n" + title)
    print("-" * len(title))


# ----------------------------------------------------------------------------
# 1.  The Gaussian triangle and the two q-Pascal recurrences
# ----------------------------------------------------------------------------

def demo_triangle(nmax: int = 6) -> None:
    banner("1. The Gaussian triangle  [n,k]_q  (rows n = 0..%d)" % nmax)
    for n in range(nmax + 1):
        row = "   ".join(pstr(qbinom(n, k)) for k in range(n + 1))
        print(f"  n={n}:  {row}")

    banner("1b. Both q-Pascal recurrences")
    for n in range(7):
        for k in range(7):
            check_a = padd(qbinom(n, k), pmul(qpow(k + 1), qbinom(n, k + 1)))
            check_b = padd(pmul(qpow(max(n - k, 0)), qbinom(n, k)), qbinom(n, k + 1))
            if qbinom(n + 1, k + 1) != check_a or qbinom(n + 1, k + 1) != check_b:
                FAILURES.append(f"q-Pascal at (n,k)=({n},{k})")
    print("  [OK ] [n+1,k+1] = [n,k] + q^{k+1}[n,k+1]        for 0 <= n,k <= 6")
    print("  [OK ] [n+1,k+1] = q^{n-k}[n,k] + [n,k+1]        for 0 <= n,k <= 6")
    print("  [OK ] degree of [n,k]_q equals k(n-k), leading coefficient 1:")
    for (n, k) in [(4, 2), (5, 2), (6, 3), (7, 3)]:
        p = qbinom(n, k)
        assert len(p) - 1 == k * (n - k) and p[-1] == 1 and all(a >= 0 for a in p)
        print(f"        [{n},{k}]_q = {pstr(p)}   (degree {len(p) - 1} = {k}*{n - k})")


# ----------------------------------------------------------------------------
# 2.  Rothe's q-binomial theorem
# ----------------------------------------------------------------------------

def rothe_lhs(n: int) -> List[Poly]:
    """Coefficients in x of prod_{i<n} (1 + q^i x); entry k is a polynomial in q."""
    coeffs: List[Poly] = [ONE]
    for i in range(n):
        new: List[Poly] = [ZERO] * (len(coeffs) + 1)
        for k, c in enumerate(coeffs):
            new[k] = padd(new[k], c)
            new[k + 1] = padd(new[k + 1], pmul(qpow(i), c))
        coeffs = new
    return coeffs


def demo_rothe(nmax: int = 7) -> None:
    banner("2. Rothe's q-binomial theorem:  prod_{i<n}(1+q^i x) = sum_k q^{k(k-1)/2} [n,k]_q x^k")
    for n in range(nmax + 1):
        lhs = rothe_lhs(n)
        rhs = [pmul(qpow(c2(k)), qbinom(n, k)) for k in range(n + 1)]
        check(f"n = {n}", lhs, rhs)
    print("  Example n = 4, coefficient of x^2:",
          pstr(rothe_lhs(4)[2]), "=  q^1 * (", pstr(qbinom(4, 2)), ")")


# ----------------------------------------------------------------------------
# 3.  The q-Vandermonde convolution
# ----------------------------------------------------------------------------

def qvandermonde_rhs(m: int, n: int, k: int) -> Poly:
    """sum_{j<=k} q^{(m-j)(k-j)} [m,j]_q [n,k-j]_q  (truncated subtraction m-j)."""
    total: Poly = ZERO
    for j in range(k + 1):
        term = pmul(qpow(max(m - j, 0) * (k - j)), pmul(qbinom(m, j), qbinom(n, k - j)))
        total = padd(total, term)
    return total


def qvandermonde_reflected(m: int, n: int, k: int) -> Poly:
    """The reflected form  sum_{j<=k} q^{j(n-(k-j))} [m,j]_q [n,k-j]_q."""
    total: Poly = ZERO
    for j in range(k + 1):
        e = j * max(n - (k - j), 0)
        total = padd(total, pmul(qpow(e), pmul(qbinom(m, j), qbinom(n, k - j))))
    return total


def demo_vandermonde(bound: int = 6) -> None:
    banner("3. q-Vandermonde:  [m+n,k]_q = sum_j q^{(m-j)(k-j)} [m,j]_q [n,k-j]_q")
    bad = 0
    for m in range(bound + 1):
        for n in range(bound + 1):
            for k in range(m + n + 2):
                if qbinom(m + n, k) != qvandermonde_rhs(m, n, k):
                    bad += 1
    check(f"all 0 <= m,n <= {bound} and 0 <= k <= m+n+1", bad, 0)

    bad = 0
    for m in range(bound + 1):
        for n in range(bound + 1):
            for k in range(m + n + 2):
                if qbinom(m + n, k) != qvandermonde_reflected(m, n, k):
                    bad += 1
    check("reflected form  q^{j(n-(k-j))}", bad, 0)

    print("  Worked example  m = n = 2, k = 2:")
    for j in range(3):
        print(f"    j={j}:  q^{max(2 - j, 0) * (2 - j)} * [2,{j}]_q * [2,{2 - j}]_q"
              f"  =  {pstr(pmul(qpow(max(2 - j, 0) * (2 - j)), pmul(qbinom(2, j), qbinom(2, 2 - j))))}")
    print("    sum  =", pstr(qvandermonde_rhs(2, 2, 2)), " =  [4,2]_q =", pstr(qbinom(4, 2)))

    banner("3b. q = 1 degenerates to the classical Vandermonde convolution")
    bad = 0
    for m in range(8):
        for n in range(8):
            for k in range(m + n + 1):
                if binom(m + n, k) != sum(binom(m, j) * binom(n, k - j) for j in range(k + 1)):
                    bad += 1
    check("C(m+n,k) = sum_j C(m,j) C(n,k-j)", bad, 0)

    banner("3c. q-analogue of  sum_j C(n,j)^2 = C(2n,n)")
    for n in range(7):
        rhs = ZERO
        for j in range(n + 1):
            rhs = padd(rhs, pmul(qpow((n - j) ** 2), pmul(qbinom(n, j), qbinom(n, j))))
        check(f"[2n,n]_q = sum_j q^{{(n-j)^2}} [n,j]_q^2   (n = {n})", qbinom(2 * n, n), rhs)


# ----------------------------------------------------------------------------
# 4.  Gauss product formula, symmetry, alternating sum
# ----------------------------------------------------------------------------

def demo_gauss() -> None:
    banner("4. Division-free Gauss product formula:  [n,k]_q (q;q)_k (q;q)_{n-k} = (q;q)_n")
    bad = 0
    for n in range(8):
        for k in range(n + 1):
            if pmul(pmul(qbinom(n, k), qpoch(k)), qpoch(n - k)) != qpoch(n):
                bad += 1
    check("all 0 <= k <= n <= 7", bad, 0)

    banner("4b. Symmetry  [n,k]_q = [n,n-k]_q")
    bad = sum(1 for n in range(9) for k in range(n + 1) if qbinom(n, k) != qbinom(n, n - k))
    check("all 0 <= k <= n <= 8", bad, 0)

    banner("4c. Gauss' alternating sum:  sum_k (-1)^k q^{k(k-1)/2} [n,k]_q = 0  for n >= 1")
    for n in range(1, 9):
        s: Poly = ZERO
        for k in range(n + 1):
            s = padd(s, pscale((-1) ** k, pmul(qpow(c2(k)), qbinom(n, k))))
        check(f"n = {n}", s, ZERO)


# ----------------------------------------------------------------------------
# 5.  Galois numbers, Rogers-Szego ladder, Gauss' evaluations at x = -1
# ----------------------------------------------------------------------------

def qgalois(n: int) -> Poly:
    """The Galois number G_n = sum_{k<=n} [n,k]_q."""
    out: Poly = ZERO
    for k in range(n + 1):
        out = padd(out, qbinom(n, k))
    return out


def qrs_at(x: int, n: int) -> Poly:
    """The Rogers-Szego polynomial H_n(x) = sum_k [n,k]_q x^k evaluated at integer x."""
    out: Poly = ZERO
    for k in range(n + 1):
        out = padd(out, pscale(x ** k, qbinom(n, k)))
    return out


def demo_galois() -> None:
    banner("5. Galois numbers G_n = sum_k [n,k]_q  (total subspace counts)")
    for n in range(6):
        g = qgalois(n)
        print(f"  G_{n}(q) = {pstr(g)}     G_{n}(2) = {peval(g, 2)}   G_{n}(3) = {peval(g, 3)}")

    banner("5b. Goldman-Rota recurrence:  G_{n+2} = 2 G_{n+1} + (q^{n+1} - 1) G_n")
    for n in range(7):
        rhs = padd(pscale(2, qgalois(n + 1)), pmul(psub(qpow(n + 1), ONE), qgalois(n)))
        check(f"n = {n}", qgalois(n + 2), rhs)

    banner("5c. Rogers-Szego ladder:  H_{n+2}(x) = (1+x)H_{n+1}(x) + (q^{n+1}-1) x H_n(x)")
    for x in (-1, 1, 2, 5):
        bad = 0
        for n in range(7):
            lhs = qrs_at(x, n + 2)
            rhs = padd(pscale(1 + x, qrs_at(x, n + 1)),
                       pmul(psub(qpow(n + 1), ONE), pscale(x, qrs_at(x, n))))
            if lhs != rhs:
                bad += 1
        check(f"x = {x}, 0 <= n <= 6", bad, 0)

    banner("5d. Gauss' evaluations at x = -1")
    for m in range(5):
        check(f"H_{2 * m + 1}(-1) = 0", qrs_at(-1, 2 * m + 1), ZERO)
    for m in range(5):
        prod_side: Poly = ONE
        for i in range(m):
            prod_side = pmul(prod_side, psub(ONE, qpow(2 * i + 1)))
        check(f"H_{2 * m}(-1) = prod_{{i<{m}}} (1 - q^{{2i+1}})", qrs_at(-1, 2 * m), prod_side)


# ----------------------------------------------------------------------------
# 6.  Cauchy's reciprocal q-binomial theorem and the negative convolution
# ----------------------------------------------------------------------------

def demo_cauchy(n: int = 4, order: int = 8) -> None:
    banner("6. Cauchy's q-binomial theorem:  (prod_{i<n}(1 - q^i X)) * sum_k [n+k-1,k]_q X^k = 1")
    prod_coeffs: List[Poly] = [ONE]
    for i in range(n):
        new: List[Poly] = [ZERO] * (len(prod_coeffs) + 1)
        for k, c in enumerate(prod_coeffs):
            new[k] = padd(new[k], c)
            new[k + 1] = psub(new[k + 1], pmul(qpow(i), c))
        prod_coeffs = new
    series = [qbinom(n + k - 1, k) for k in range(order + 1)]
    conv: List[Poly] = []
    for t in range(order + 1):
        acc: Poly = ZERO
        for a in range(min(t, len(prod_coeffs) - 1) + 1):
            acc = padd(acc, pmul(prod_coeffs[a], series[t - a]))
        conv.append(acc)
    check(f"n = {n}, coefficients of X^0..X^{order}", conv, [ONE] + [ZERO] * order)

    banner("6b. Negative (Cauchy) q-Vandermonde: "
           "[m+n+k-1,k]_q = sum_j q^{m(k-j)} [m+j-1,j]_q [n+k-j-1,k-j]_q")
    bad = 0
    for m in range(5):
        for nn in range(5):
            for k in range(6):
                rhs: Poly = ZERO
                for j in range(k + 1):
                    rhs = padd(rhs, pmul(qpow(m * (k - j)),
                                         pmul(qbinom(max(m + j - 1, 0), j),
                                              qbinom(max(nn + (k - j) - 1, 0), k - j))))
                if qbinom(max(m + nn + k - 1, 0), k) != rhs:
                    bad += 1
    check("all 0 <= m,n <= 4, 0 <= k <= 5", bad, 0)


# ----------------------------------------------------------------------------
# 7.  The q-Lucas theorem at a root of unity
# ----------------------------------------------------------------------------

def demo_qlucas() -> None:
    banner("7. q-Lucas at q = -1:  [n,k]_{-1} = C(n/2, k/2) * [n mod 2, k mod 2]_{-1}")
    bad = 0
    for n in range(14):
        for k in range(n + 1):
            lhs = peval(qbinom(n, k), -1)
            rhs = binom(n // 2, k // 2) * peval(qbinom(n % 2, k % 2), -1)
            if lhs != rhs:
                bad += 1
    check("all 0 <= k <= n <= 13", bad, 0)
    print("  Consequences:  [2a,2b]_{-1} = C(a,b)   and   [2a,2b+1]_{-1} = 0")
    print("  row n = 6 at q = -1:", [peval(qbinom(6, k), -1) for k in range(7)],
          " = C(3,k/2) pattern", [binom(3, k) for k in range(4)])


# ----------------------------------------------------------------------------
# 8.  Grassmannian meaning: counting subspaces of F_q^n
# ----------------------------------------------------------------------------

def count_subspaces_F2(n: int, k: int) -> int:
    """Brute-force count of k-dimensional subspaces of F_2^n (small n only)."""
    vectors = list(product((0, 1), repeat=n))
    subspaces = set()
    for combo in product(range(len(vectors)), repeat=k):
        basis = [vectors[i] for i in combo]
        span = {tuple([0] * n)}
        for b in basis:
            span |= {tuple((x + y) % 2 for x, y in zip(v, b)) for v in span}
        if len(span) == 2 ** k:
            subspaces.add(frozenset(span))
    return len(subspaces)


def demo_grassmann() -> None:
    banner("8. Gaussian binomials count subspaces:  |Gr(k, F_q^n)| = [n,k]_q")
    for (n, k) in [(3, 1), (4, 1), (4, 2), (4, 3)]:
        brute = count_subspaces_F2(n, k)
        formula = peval(qbinom(n, k), 2)
        check(f"k = {k}, n = {n}, q = 2:  brute force {brute} = [{n},{k}]_2 = {formula}",
              brute, formula)

    banner("8b. The projective space PG(3,q)")
    for q in (2, 3, 4, 5):
        through_point = peval(qbinom(3, 1), q)
        lines = peval(qbinom(4, 2), q)
        assert through_point == 1 + q + q * q
        assert lines == (q * q + 1) * (q * q + q + 1)
        print(f"  q = {q}:  lines through a point = [3,1]_q = {through_point};"
              f"  total lines = [4,2]_q = {lines} = (q^2+1)(q^2+q+1)")

    banner("8c. The same line count as a q-Vandermonde split 4 = 2 + 2")
    print("  [4,2]_q = q^4 * [2,0][2,2] + q * [2,1][2,1] + [2,2][2,0]")
    print("          =", pstr(qvandermonde_rhs(2, 2, 2)),
          " = q^4 + q(1+q)^2 + 1")
    check("identity of polynomials", qvandermonde_rhs(2, 2, 2), qbinom(4, 2))


# ----------------------------------------------------------------------------

def main() -> None:
    print(__doc__)
    demo_triangle()
    demo_rothe()
    demo_vandermonde()
    demo_gauss()
    demo_galois()
    demo_cauchy()
    demo_qlucas()
    demo_grassmann()
    banner("Summary")
    if FAILURES:
        print("  FAILED checks:")
        for f in FAILURES:
            print("   -", f)
    else:
        print("  All identities verified exactly over Z[q] in the stated ranges.")


if __name__ == "__main__":
    main()

"""
Gaussian binomials at roots of unity: the q-Lucas theorem and cyclic sieving
===========================================================================

Two experiments, both self-contained:

1. The q-Lucas theorem.  For a primitive d-th root of unity z,
       [n,k]_z = C(n/d, k/d) * [n mod d, k mod d]_z,
   so the Gaussian triangle factorises into an ordinary binomial coefficient
   governing whole blocks of size d and a small Gaussian residue inside a block.
   The exact special case z = -1 (the "q = -1 phenomenon") gives
       [2a,2b]_{-1} = C(a,b),   [2a,2b+1]_{-1} = 0.

2. Cyclic sieving.  Rotating an n-element cycle acts on the k-subsets.  The
   number of k-subsets fixed by rotation through j positions is exactly the value
   of [n,k]_q at q = exp(2*pi*i*j/n).  This is the cyclic sieving phenomenon, and
   it is the combinatorial content of the q-Lucas evaluations.

Run:  python3 demo_roots.py
"""

from __future__ import annotations

import cmath
from functools import lru_cache
from itertools import combinations
from typing import List, Sequence, Tuple

Poly = Tuple[int, ...]


def trim(c: Sequence[int]) -> Poly:
    out = list(c)
    while out and out[-1] == 0:
        out.pop()
    return tuple(out)


def padd(p: Poly, r: Poly) -> Poly:
    n = max(len(p), len(r))
    return trim([(p[i] if i < len(p) else 0) + (r[i] if i < len(r) else 0) for i in range(n)])


def pshift(e: int, p: Poly) -> Poly:
    return trim([0] * e + list(p)) if p else ()


@lru_cache(maxsize=None)
def qbinom(n: int, k: int) -> Poly:
    """[n,k]_q by the first q-Pascal recursion."""
    if k < 0 or n < 0 or k > n:
        return ()
    if k == 0:
        return (1,)
    return padd(qbinom(n - 1, k - 1), pshift(k, qbinom(n - 1, k)))


def binom(n: int, k: int) -> int:
    if k < 0 or k > n:
        return 0
    num, den = 1, 1
    for i in range(k):
        num *= n - i
        den *= i + 1
    return num // den


def eval_int(p: Poly, q: int) -> int:
    acc = 0
    for a in reversed(p):
        acc = acc * q + a
    return acc


def eval_complex(p: Poly, z: complex) -> complex:
    acc = 0j
    for a in reversed(p):
        acc = acc * z + a
    return acc


def demo_qlucas_minus_one(nmax: int = 12) -> None:
    print("\n1a. The q = -1 phenomenon:  [2a,2b]_{-1} = C(a,b),  [2a,2b+1]_{-1} = 0")
    ok = True
    for a in range(nmax // 2 + 1):
        for b in range(a + 1):
            if eval_int(qbinom(2 * a, 2 * b), -1) != binom(a, b):
                ok = False
            if eval_int(qbinom(2 * a, 2 * b + 1), -1) != 0:
                ok = False
    print(f"   verified for all a <= {nmax // 2}: {ok}")
    for n in (4, 6, 8):
        print(f"   row n={n} at q=-1: {[eval_int(qbinom(n, k), -1) for k in range(n + 1)]}")


def demo_qlucas_general(d: int = 3, nmax: int = 14) -> None:
    print(f"\n1b. q-Lucas at a primitive {d}-th root of unity (numerically, |error| shown)")
    z = cmath.exp(2j * cmath.pi / d)
    worst = 0.0
    for n in range(nmax + 1):
        for k in range(n + 1):
            lhs = eval_complex(qbinom(n, k), z)
            rhs = binom(n // d, k // d) * eval_complex(qbinom(n % d, k % d), z)
            worst = max(worst, abs(lhs - rhs))
    print(f"   max |[n,k]_z - C(n/d,k/d)[n mod d, k mod d]_z| over n <= {nmax}: {worst:.2e}")
    print("   consequence: [n,k]_z = 0 whenever d | n and d does not divide k, e.g.")
    for (n, k) in [(6, 1), (6, 2), (9, 4), (12, 5)]:
        if n % d == 0 and k % d != 0:
            print(f"     [{n},{k}]_z = {eval_complex(qbinom(n, k), z):.3e}")


def rotations_fixing(n: int, k: int, j: int) -> int:
    """Number of k-subsets of Z/n fixed by rotation through j positions."""
    count = 0
    for s in combinations(range(n), k):
        t = tuple(sorted((x + j) % n for x in s))
        if t == s:
            count += 1
    return count


def demo_cyclic_sieving(n: int = 8, k: int = 4) -> None:
    print(f"\n2. Cyclic sieving for k-subsets of Z/{n} with k = {k}")
    print("   j | fixed k-subsets | [n,k]_q at q = exp(2*pi*i*j/n)")
    for j in range(n):
        z = cmath.exp(2j * cmath.pi * j / n)
        val = eval_complex(qbinom(n, k), z)
        fixed = rotations_fixing(n, k, j)
        flag = "ok" if abs(val - fixed) < 1e-8 else "MISMATCH"
        print(f"  {j:2d} | {fixed:15d} | {val.real:10.4f}{val.imag:+.1e}i   {flag}")


def main() -> None:
    print(__doc__)
    demo_qlucas_minus_one()
    demo_qlucas_general()
    demo_cyclic_sieving()
    demo_cyclic_sieving(n=6, k=3)


if __name__ == "__main__":
    main()

