"""Gaussian triangle by the dual q-Pascal recursions (exact, subtraction-free)."""

from __future__ import annotations

from typing import Dict, List, Sequence, Tuple

Poly = Tuple[int, ...]  # index i holds the coefficient of q^i


def trim(c: Sequence[int]) -> Poly:
    out = list(c)
    while out and out[-1] == 0:
        out.pop()
    return tuple(out)


def padd(p: Poly, r: Poly) -> Poly:
    n = max(len(p), len(r))
    return trim([(p[i] if i < len(p) else 0) + (r[i] if i < len(r) else 0) for i in range(n)])


def pshift(e: int, p: Poly) -> Poly:
    """Multiply by the monomial q^e."""
    return trim([0] * e + list(p)) if p else ()


def gaussian_triangle(N: int) -> List[List[Poly]]:
    """Return rows 0..N of the Gaussian triangle, each entry a polynomial in q.

    Uses the first q-Pascal recursion
        [n+1, k+1] = [n, k] + q^{k+1} [n, k+1],
    with [n, 0] = 1 and [0, k+1] = 0.  No subtraction and no division occur, so
    every intermediate coefficient is a non-negative integer and the procedure is
    valid verbatim over any commutative semiring.
    """
    rows: List[List[Poly]] = [[(1,)]]
    for n in range(N):
        prev = rows[-1]
        row: List[Poly] = [(1,)]
        for k in range(n + 1):
            left = prev[k]                                   # [n, k]
            right = prev[k + 1] if k + 1 < len(prev) else ()  # [n, k+1]
            row.append(padd(left, pshift(k + 1, right)))
        rows.append(row)
    return rows


def verify_second_recursion(rows: List[List[Poly]]) -> bool:
    """Check [n+1,k+1] = q^{n-k} [n,k] + [n,k+1] on the computed table."""
    for n in range(len(rows) - 1):
        for k in range(n + 1):
            left = rows[n][k]
            right = rows[n][k + 1] if k + 1 < len(rows[n]) else ()
            if rows[n + 1][k + 1] != padd(pshift(max(n - k, 0), left), right):
                return False
    return True


def evaluate(p: Poly, q: int) -> int:
    """Horner evaluation at an integer q (e.g. a prime power)."""
    acc = 0
    for a in reversed(p):
        acc = acc * q + a
    return acc


if __name__ == "__main__":
    rows = gaussian_triangle(6)
    for n, row in enumerate(rows):
        print(n, [list(p) for p in row])
    print("second recursion holds:", verify_second_recursion(rows))
    print("[4,2] at q = 2 (planes in F_2^4):", evaluate(rows[4][2], 2))

"""Rothe expansion: the product prod_{i<n}(1 + q^i x) and its x-coefficients."""

from __future__ import annotations

from typing import List, Sequence, Tuple

Poly = Tuple[int, ...]


def trim(c: Sequence[int]) -> Poly:
    out = list(c)
    while out and out[-1] == 0:
        out.pop()
    return tuple(out)


def padd(p: Poly, r: Poly) -> Poly:
    n = max(len(p), len(r))
    return trim([(p[i] if i < len(p) else 0) + (r[i] if i < len(r) else 0) for i in range(n)])


def pshift(e: int, p: Poly) -> Poly:
    return trim([0] * e + list(p)) if p else ()


def rothe_coefficients(n: int) -> List[Poly]:
    """Coefficients in x of prod_{i=0}^{n-1} (1 + q^i x).

    Each factor updates the coefficient list in place by
        c_k  <-  c_k + q^i c_{k-1},
    so the whole expansion costs O(n^2) polynomial operations.  By Rothe's
    q-binomial theorem the output equals  c_k = q^{k(k-1)/2} [n, k]_q.
    """
    coeffs: List[Poly] = [(1,)]
    for i in range(n):
        new: List[Poly] = [()] * (len(coeffs) + 1)
        for k, c in enumerate(coeffs):
            new[k] = padd(new[k], c)
            new[k + 1] = padd(new[k + 1], pshift(i, c))
        coeffs = new
    return coeffs


def strip_triangular_factor(n: int) -> List[Poly]:
    """Recover [n,k]_q from the Rothe coefficients by removing q^{k(k-1)/2}.

    The division by the monomial q^{k(k-1)/2} is exact: it is a shift of the
    coefficient list, and the discarded low-order coefficients are all zero.
    """
    out: List[Poly] = []
    for k, c in enumerate(rothe_coefficients(n)):
        e = k * (k - 1) // 2
        assert all(a == 0 for a in c[:e]), "triangular factor does not divide"
        out.append(trim(c[e:]))
    return out


if __name__ == "__main__":
    for n in range(6):
        print(n, [list(p) for p in strip_triangular_factor(n)])

"""The q-Vandermonde splitting oracle and the Rogers-Szego ladder."""

from __future__ import annotations

from functools import lru_cache
from typing import List, Sequence, Tuple

Poly = Tuple[int, ...]


def trim(c: Sequence[int]) -> Poly:
    out = list(c)
    while out and out[-1] == 0:
        out.pop()
    return tuple(out)


def padd(p: Poly, r: Poly) -> Poly:
    n = max(len(p), len(r))
    return trim([(p[i] if i < len(p) else 0) + (r[i] if i < len(r) else 0) for i in range(n)])


def psub(p: Poly, r: Poly) -> Poly:
    n = max(len(p), len(r))
    return trim([(p[i] if i < len(p) else 0) - (r[i] if i < len(r) else 0) for i in range(n)])


def pmul(p: Poly, r: Poly) -> Poly:
    if not p or not r:
        return ()
    out = [0] * (len(p) + len(r) - 1)
    for i, a in enumerate(p):
        if a:
            for j, b in enumerate(r):
                out[i + j] += a * b
    return trim(out)


def pscale(c: int, p: Poly) -> Poly:
    return trim([c * a for a in p])


def pshift(e: int, p: Poly) -> Poly:
    return trim([0] * e + list(p)) if p else ()


@lru_cache(maxsize=None)
def qbinom(n: int, k: int) -> Poly:
    """[n,k]_q via the first q-Pascal recursion, memoised."""
    if k < 0 or n < 0 or k > n:
        return ()
    if k == 0:
        return (1,)
    return padd(qbinom(n - 1, k - 1), pshift(k, qbinom(n - 1, k)))


def vandermonde_terms(m: int, n: int, k: int) -> List[Tuple[int, Poly]]:
    """The individual terms  q^{(m-j)(k-j)} [m,j]_q [n,k-j]_q  for j = 0..k.

    Returns pairs (exponent, term).  Summing the terms gives [m+n, k]_q; over a
    finite field with q elements the j-th term counts the k-dimensional subspaces
    W of F_q^m + F_q^n with dim(W cap F_q^m) = j, the monomial q^{(m-j)(k-j)}
    counting the gluing homomorphisms of the corresponding Schubert cell.
    Cost: O(k) polynomial multiplications on top of a memoised triangle.
    """
    terms: List[Tuple[int, Poly]] = []
    for j in range(k + 1):
        e = max(m - j, 0) * (k - j)
        terms.append((e, pshift(e, pmul(qbinom(m, j), qbinom(n, k - j)))))
    return terms


def qbinom_by_splitting(m: int, n: int, k: int) -> Poly:
    """Compute [m+n,k]_q from two smaller triangles by the convolution."""
    total: Poly = ()
    for _, t in vandermonde_terms(m, n, k):
        total = padd(total, t)
    return total


def rogers_szego_ladder(N: int) -> List[List[Poly]]:
    """H_0..H_N, each returned as its list of x-coefficients (polynomials in q).

    Iterates the three-term ladder
        H_{n+2}(x) = (1+x) H_{n+1}(x) + (q^{n+1} - 1) x H_n(x),
    starting from H_0 = 1 and H_1 = 1 + x.  This produces the row sums and row
    generating functions of the Gaussian triangle in O(N) ladder steps instead of
    the O(N^2) entries of the triangle itself.
    """
    H: List[List[Poly]] = [[(1,)], [(1,), (1,)]]
    for n in range(N - 1):
        a, b = H[n], H[n + 1]
        deg = n + 2
        out: List[Poly] = [()] * (deg + 1)
        for k, c in enumerate(b):            # (1 + x) H_{n+1}
            out[k] = padd(out[k], c)
            out[k + 1] = padd(out[k + 1], c)
        w = psub(pshift(n + 1, (1,)), (1,))  # q^{n+1} - 1
        for k, c in enumerate(a):            # (q^{n+1} - 1) x H_n
            out[k + 1] = padd(out[k + 1], pmul(w, c))
        H.append([trim(c) for c in out])
    return H[: N + 1]


def galois_numbers(N: int) -> List[Poly]:
    """G_n = H_n(1) = sum_k [n,k]_q, the total subspace counts."""
    out: List[Poly] = []
    for coeffs in rogers_szego_ladder(N):
        acc: Poly = ()
        for c in coeffs:
            acc = padd(acc, c)
        out.append(acc)
    return out


if __name__ == "__main__":
    print("[4,2] by splitting 2+2:", list(qbinom_by_splitting(2, 2, 2)))
    print("terms:", [(e, list(t)) for e, t in vandermonde_terms(2, 2, 2)])
    print("Galois numbers:", [list(g) for g in galois_numbers(6)])

