"""Visualisation: the coefficient landscape of the Gaussian binomials.

Left panel:  a heatmap of the coefficients of [n,k]_q for a fixed n, showing the
unimodal partition-counting profile and the degree parabola k(n-k).
Right panel: the Gaussian triangle evaluated at several values of q, on a log
scale, showing how the deformation interpolates between subset counts (q = 1)
and subspace counts (q = 2, 3, 4).

Requires matplotlib and numpy.
"""

from __future__ import annotations

from functools import lru_cache
from typing import List, Sequence, Tuple

import matplotlib.pyplot as plt
import numpy as np

Poly = Tuple[int, ...]


def trim(c: Sequence[int]) -> Poly:
    out = list(c)
    while out and out[-1] == 0:
        out.pop()
    return tuple(out)


def padd(p: Poly, r: Poly) -> Poly:
    n = max(len(p), len(r))
    return trim([(p[i] if i < len(p) else 0) + (r[i] if i < len(r) else 0) for i in range(n)])


def pshift(e: int, p: Poly) -> Poly:
    return trim([0] * e + list(p)) if p else ()


@lru_cache(maxsize=None)
def qbinom(n: int, k: int) -> Poly:
    if k < 0 or n < 0 or k > n:
        return ()
    if k == 0:
        return (1,)
    return padd(qbinom(n - 1, k - 1), pshift(k, qbinom(n - 1, k)))


def evaluate(p: Poly, q: float) -> float:
    acc = 0.0
    for a in reversed(p):
        acc = acc * q + a
    return acc


def main(n: int = 12) -> None:
    maxdeg = max(len(qbinom(n, k)) for k in range(n + 1))
    grid = np.zeros((n + 1, maxdeg))
    for k in range(n + 1):
        for i, a in enumerate(qbinom(n, k)):
            grid[k, i] = a

    fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(13, 5))

    im = ax1.imshow(grid, aspect="auto", origin="lower", cmap="magma")
    ax1.plot([k * (n - k) for k in range(n + 1)], range(n + 1), "c.-", lw=1.2,
             label=r"degree $k(n-k)$")
    ax1.set_xlabel(r"power of $q$")
    ax1.set_ylabel(r"$k$")
    ax1.set_title(rf"coefficients of $[{n},k]_q$ (partitions in a $k\times({n}-k)$ box)")
    ax1.legend(loc="upper right")
    fig.colorbar(im, ax=ax1, label="coefficient")

    ks = np.arange(n + 1)
    for q, style in [(1, "o-"), (2, "s-"), (3, "^-"), (4, "d-")]:
        vals = [evaluate(qbinom(n, int(k)), q) for k in ks]
        ax2.semilogy(ks, vals, style, label=rf"$q={q}$")
    ax2.set_xlabel(r"$k$")
    ax2.set_ylabel(r"$[n,k]_q$  (log scale)")
    ax2.set_title(rf"row $n={n}$: subsets ($q=1$) versus subspaces ($q=2,3,4$)")
    ax2.grid(alpha=0.3)
    ax2.legend()

    fig.suptitle("The Gaussian triangle: one sheet carrying both combinatorics and geometry")
    fig.tight_layout()
    fig.savefig("gaussian_coefficients.png", dpi=150)
    print("wrote gaussian_coefficients.png")


if __name__ == "__main__":
    main()

"""Visualisation: the q-Vandermonde convolution as a Schubert cell census.

Left panel:  for a chosen split m + n and a chosen k, the contribution of each
term q^{(m-j)(k-j)} [m,j]_q [n,k-j]_q to [m+n,k]_q, evaluated at a prime power q.
Each bar is the number of k-dimensional subspaces meeting the first summand in
exactly j dimensions; the bars sum to the total.
Right panel: the Galois numbers G_n (all subspaces of F_q^n) against 2^n (all
subsets of an n-set), showing the growth gap created by the deformation.

Requires matplotlib and numpy.
"""

from __future__ import annotations

from functools import lru_cache
from typing import List, Sequence, Tuple

import matplotlib.pyplot as plt
import numpy as np

Poly = Tuple[int, ...]


def trim(c: Sequence[int]) -> Poly:
    out = list(c)
    while out and out[-1] == 0:
        out.pop()
    return tuple(out)


def padd(p: Poly, r: Poly) -> Poly:
    n = max(len(p), len(r))
    return trim([(p[i] if i < len(p) else 0) + (r[i] if i < len(r) else 0) for i in range(n)])


def pmul(p: Poly, r: Poly) -> Poly:
    if not p or not r:
        return ()
    out = [0] * (len(p) + len(r) - 1)
    for i, a in enumerate(p):
        for j, b in enumerate(r):
            out[i + j] += a * b
    return trim(out)


def pshift(e: int, p: Poly) -> Poly:
    return trim([0] * e + list(p)) if p else ()


@lru_cache(maxsize=None)
def qbinom(n: int, k: int) -> Poly:
    if k < 0 or n < 0 or k > n:
        return ()
    if k == 0:
        return (1,)
    return padd(qbinom(n - 1, k - 1), pshift(k, qbinom(n - 1, k)))


def evaluate(p: Poly, q: int) -> int:
    acc = 0
    for a in reversed(p):
        acc = acc * q + a
    return acc


def galois(n: int) -> Poly:
    acc: Poly = ()
    for k in range(n + 1):
        acc = padd(acc, qbinom(n, k))
    return acc


def main(m: int = 3, n: int = 3, k: int = 3, q: int = 2, nmax: int = 9) -> None:
    js = list(range(k + 1))
    terms = []
    labels = []
    for j in js:
        e = max(m - j, 0) * (k - j)
        val = q ** e * evaluate(qbinom(m, j), q) * evaluate(qbinom(n, k - j), q)
        terms.append(val)
        labels.append(rf"$j={j}$" + "\n" + rf"$q^{{{e}}}$")
    total = evaluate(qbinom(m + n, k), q)

    fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(13, 5))
    bars = ax1.bar(js, terms, color=plt.cm.viridis(np.linspace(0.15, 0.85, len(js))))
    ax1.set_xticks(js)
    ax1.set_xticklabels(labels)
    ax1.set_xlabel(r"$\dim(W \cap \mathbb{F}_q^m) = j$")
    ax1.set_ylabel("number of subspaces")
    ax1.set_title(rf"$[{m+n},{k}]_{{{q}}} = {total} = \sum_j q^{{(m-j)(k-j)}}[{m},j]_q[{n},k-j]_q$")
    for b, v in zip(bars, terms):
        ax1.text(b.get_x() + b.get_width() / 2, v, str(v), ha="center", va="bottom")
    assert sum(terms) == total

    ns = np.arange(nmax + 1)
    gvals = [evaluate(galois(int(i)), q) for i in ns]
    ax2.semilogy(ns, gvals, "o-", label=rf"Galois numbers $G_n$ at $q={q}$")
    ax2.semilogy(ns, [2 ** int(i) for i in ns], "s--", label=r"$2^n$ (subsets, $q=1$)")
    ax2.set_xlabel(r"$n$")
    ax2.set_ylabel("count (log scale)")
    ax2.set_title("all subspaces of $\\mathbb{F}_q^n$ versus all subsets of an $n$-set")
    ax2.grid(alpha=0.3)
    ax2.legend()

    fig.suptitle("q-Vandermonde: splitting a Grassmannian into Schubert cells")
    fig.tight_layout()
    fig.savefig("qvandermonde_cells.png", dpi=150)
    print("wrote qvandermonde_cells.png")


if __name__ == "__main__":
    main()

